import { Hono } from "hono";
import { adsRoutes } from "#/modules/ads/index.ts";

export function createApp(): Hono {
  const app = new Hono();
  app.route("/ads", adsRoutes);
  return app;
}

src/modules/ads/types.ts:
export interface Ad {
  id: string;
  budgetCents: number;
}

src/modules/ads/routes.ts:
import { Hono } from "hono";
import { listAds } from "./data/ads.ts";
import { formatBudget } from "./domain/budget.ts";

export const adsRoutes = new Hono().get("/", async (c) => {
  const ads = await listAds();
  return c.json(ads.map((ad) => ({ ...ad, budget: formatBudget(ad.budgetCents) })));
});

src/modules/ads/data/ads.ts:
import { db } from "#/backend/client.ts";
import type { Ad } from "../types.ts";

export async function listAds(): Promise<Ad[]> {
  const { data } = await db.from("ads").select("id, budgetCents");
  return data ?? [];
}

